import { field, textarea, select, checkbox, htmlEscape, attrEscape, normalizeUrl } from "../tool-core.js";export default {form: `<label class="check-row"><input id="uniform" type="checkbox" onchange="var c=document.getElementById('corner-fields'),u=document.getElementById('uniform-field');c.style.display=this.checked?'none':'';u.style.display=this.checked?'':'none';"><span>Use uniform value</span></label><div id="uniform-field" style="display:none"><div class="field"><label for="radius">Border radius</label><div style="display:flex;gap:4px"><input id="radius" type="number" value="8" style="flex:1"><select style="width:56px;flex:none" id="radius-unit"><option value="px" selected>px</option><option value="rem">rem</option><option value="%">%</option></select></div></div></div><div id="corner-fields"><div style="display:flex;gap:14px"><div class="field" style="flex:1"><label for="tl">Top-left</label><div style="display:flex;gap:4px"><input id="tl" type="number" value="8" style="flex:1"><select style="width:56px;flex:none" id="tl-unit"><option value="px" selected>px</option><option value="rem">rem</option><option value="%">%</option></select></div></div><div class="field" style="flex:1"><label for="tr">Top-right</label><div style="display:flex;gap:4px"><input id="tr" type="number" value="8" style="flex:1"><select style="width:56px;flex:none" id="tr-unit"><option value="px" selected>px</option><option value="rem">rem</option><option value="%">%</option></select></div></div></div><div style="display:flex;gap:14px;margin-top:14px"><div class="field" style="flex:1"><label for="br">Bottom-right</label><div style="display:flex;gap:4px"><input id="br" type="number" value="8" style="flex:1"><select style="width:56px;flex:none" id="br-unit"><option value="px" selected>px</option><option value="rem">rem</option><option value="%">%</option></select></div></div><div class="field" style="flex:1"><label for="bl">Bottom-left</label><div style="display:flex;gap:4px"><input id="bl" type="number" value="8" style="flex:1"><select style="width:56px;flex:none" id="bl-unit"><option value="px" selected>px</option><option value="rem">rem</option><option value="%">%</option></select></div></div></div></div>`,generate(root) {const uniform = root.querySelector("#uniform").checked;let css;if (uniform) {const v = root.querySelector("#radius").value || "0";const u = root.querySelector("#radius-unit").value;css = `border-radius: ${v}${u};`;} else {css = `border-radius: ${root.querySelector("#tl").value || "0"}${root.querySelector("#tl-unit").value} ${root.querySelector("#tr").value || "0"}${root.querySelector("#tr-unit").value} ${root.querySelector("#br").value || "0"}${root.querySelector("#br-unit").value} ${root.querySelector("#bl").value || "0"}${root.querySelector("#bl-unit").value};`;}const preview = `<div style="width:200px;height:120px;background:linear-gradient(135deg,#6366f1,#a855f7);${css}margin:1rem auto"></div>`;return { output: css, preview };}};